import{_ as a,a as r,b as t,c as n,d as i}from"./chunks/training-5.D_Ul-Com.js";import{_ as o,c as l,o as s,ae as h}from"./chunks/framework.BbFa6TS3.js";const A=JSON.parse('{"title":"AI 训练方法","description":"","frontmatter":{},"headers":[],"relativePath":"fe/ai/training.md","filePath":"fe/ai/training.md"}'),g={name:"fe/ai/training.md"};function c(p,e,f,m,w,u){return s(),l("div",null,e[0]||(e[0]=[h('<h1 id="ai-训练方法" tabindex="-1">AI 训练方法 <a class="header-anchor" href="#ai-训练方法" aria-label="Permalink to &quot;AI 训练方法&quot;">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>人工智能（AI）的飞速发展，特别是近年来大型语言模型（LLMs）的崛起，极大地改变了我们与技术互动的方式。这些模型的强大能力并非一蹴而就，而是建立在一系列复杂而精妙的训练方法之上。理解这些核心训练方法——包括规模法则、预训练、微调、人类反馈强化学习（RLHF）和少样本学习——对于把握 AI 技术的发展脉络、预测其未来趋势以及有效应用 AI 系统至关重要。本文将对这些关键的 AI 训练方法进行深入解析，旨在为读者提供一个全面而详细的知识普及。</p><p>我们将探讨每种方法的原理、在 AI 发展中的作用、相互之间的联系以及它们如何共同推动了当前 AI 能力的边界。从宏观的“规模法则”揭示模型性能与资源投入的普遍规律，到“预训练”奠定模型的基础认知能力，再到“微调”实现任务特化，以及“RLHF”确保模型行为与人类价值观对齐，最后是“少样本学习”展现模型在数据稀缺场景下的高效适应性。通过对这些方法的系统性梳理，我们希望能帮助读者更深刻地理解 AI 模型是如何被构建、训练和优化的，从而更好地驾驭这一变革性的技术。</p><h2 id="规模法则-scaling-laws" tabindex="-1">规模法则（Scaling Laws） <a class="header-anchor" href="#规模法则-scaling-laws" aria-label="Permalink to &quot;规模法则（Scaling Laws）&quot;">​</a></h2><p><img src="'+a+'" alt="training"></p><p>规模法则描述了 AI 模型性能与训练规模（包括参数数量、数据集大小和计算资源）之间存在的普遍且可预测的数学关系。这一概念并非 AI 领域独有，其根源可追溯到生物学中对生物体生理和形态特征随体型变化的幂律关系研究 [1]。在 AI 领域，规模法则揭示了一个核心洞察：在一定范围内，模型的性能会随着其规模的增加而以可预测的幂律形式提升 [2]。</p><h3 id="核心要素与表现" tabindex="-1">核心要素与表现 <a class="header-anchor" href="#核心要素与表现" aria-label="Permalink to &quot;核心要素与表现&quot;">​</a></h3><p>AI 领域的规模法则主要关注以下三个核心要素：</p><ol><li><strong>模型参数量（Model Size）</strong>：指模型中可学习参数的数量。研究表明，当模型参数量增加时，模型的性能（例如，在语言模型中表现为交叉熵损失的降低）通常会显著提升 [3]。这种提升并非线性，而是遵循幂律关系，即性能提升的幅度会随着参数量的几何级增长而呈现出一定的规律性。</li><li><strong>训练数据量（Dataset Size）</strong>：指用于训练模型的数据总量。更大的、更多样化的数据集能够让模型学习到更丰富的模式和更泛化的知识。在许多情况下，模型性能的提升与训练数据量的对数或幂律关系相关 [4]。</li><li><strong>计算资源（Compute）</strong>：指训练模型所需的计算量，通常以浮点运算次数（FLOPs）衡量。计算资源的投入直接影响模型能够处理的数据量和参数量。在固定模型大小和数据集大小的情况下，增加计算资源通常也能带来性能的提升 [5]。</li></ol><p>这些要素之间的关系可以用数学公式表示，例如，OpenAI 在 2020 年的一项开创性研究中发现，语言模型的损失（L）与模型大小（N）、数据集大小（D）和计算量（C）之间存在幂律关系 [3]。这意味着，即使在不改变模型架构的情况下，仅仅通过扩大规模，也能持续提升模型性能。</p><h3 id="意义与影响" tabindex="-1">意义与影响 <a class="header-anchor" href="#意义与影响" aria-label="Permalink to &quot;意义与影响&quot;">​</a></h3><p>规模法则对 AI 领域产生了深远的影响：</p><ul><li><strong>指导模型设计与资源配置</strong>：规模法则为 AI 研究者和开发者提供了明确的指导方向。它表明，为了获得更强大的 AI 能力，持续投入更多的计算资源、构建更大的模型和收集更多的数据是有效的途径。这促使了“大力出奇迹”的范式，推动了大型语言模型（LLMs）和大型视觉模型的发展 [6]。</li><li><strong>预测模型性能</strong>：通过规模法则，研究人员可以在训练大型模型之前，通过训练较小规模的模型来预测更大规模模型的性能，从而优化资源分配和实验设计 [7]。</li><li><strong>解释涌现能力（Emergent Abilities）</strong>：随着模型规模的不断扩大，AI 模型不仅在现有任务上表现更好，还会展现出在小模型中不曾出现的“涌现能力” [8]。这些能力通常是模型在处理复杂任务时表现出的新颖行为或技能，例如复杂推理、多步问题解决等。规模法则为理解这些涌现能力的出现提供了理论基础，即它们可能是模型规模达到一定阈值后，内部复杂性增加的自然结果。</li><li><strong>推动 AI 基础设施发展</strong>：为了满足训练大规模模型所需的巨大计算需求，规模法则也间接推动了高性能计算硬件（如 GPU、TPU）和分布式训练技术的发展 [9]。</li></ul><h3 id="挑战与未来" tabindex="-1">挑战与未来 <a class="header-anchor" href="#挑战与未来" aria-label="Permalink to &quot;挑战与未来&quot;">​</a></h3><p>尽管规模法则在 AI 发展中扮演了重要角色，但也面临一些挑战。例如，有研究指出，随着模型规模的进一步扩大，性能提升的边际效益可能开始递减，即“回报递减”现象 [10]。这促使研究人员开始探索除了简单扩大规模之外的其他优化途径，例如更高效的训练算法、更好的数据质量、以及模型架构的创新等。未来的研究可能会更侧重于如何以更低的成本、更有效率的方式实现模型性能的提升，而不仅仅是依赖于规模的无限扩大。</p><p><strong>参考文献：</strong></p><p>[1] 知乎. AI 中的 Scaling Laws 的原理是什么？[在线]. Available: <a href="https://www.zhihu.com/question/9809458451" target="_blank" rel="noreferrer">https://www.zhihu.com/question/9809458451</a> [2] NVIDIA Blog. How Scaling Laws Drive Smarter, More Powerful AI. [在线]. Available: <a href="https://blogs.nvidia.com/blog/ai-scaling-laws/" target="_blank" rel="noreferrer">https://blogs.nvidia.com/blog/ai-scaling-laws/</a> [3] OpenAI. Scaling Laws for Neural Language Models. [在线]. Available: <a href="https://openai.com/index/scaling-laws-for-neural-language-models/" target="_blank" rel="noreferrer">https://openai.com/index/scaling-laws-for-neural-language-models/</a> [4] TechTarget. What is fine-tuning? [在线]. Available: <a href="https://www.techtarget.com/searchenterpriseai/definition/fine-tuning" target="_blank" rel="noreferrer">https://www.techtarget.com/searchenterpriseai/definition/fine-tuning</a> [5] RCR Wireless. The three AI scaling laws and what they mean for AI infrastructure. [在线]. Available: <a href="https://www.rcrwireless.com/20250120/fundamentals/three-ai-scaling-laws-what-they-mean-for-ai-infrastructure" target="_blank" rel="noreferrer">https://www.rcrwireless.com/20250120/fundamentals/three-ai-scaling-laws-what-they-mean-for-ai-infrastructure</a> [6] 澎湃新闻. AI 规模法则：大力何以出奇迹？[在线]. Available: <a href="https://www.thepaper.cn/newsDetail_forward_26561031" target="_blank" rel="noreferrer">https://www.thepaper.cn/newsDetail_forward_26561031</a> [7] Deep (Learning) Focus. Scaling Laws for LLMs: From GPT-3 to o3. [在线]. Available: <a href="https://cameronrwolfe.substack.com/p/llm-scaling-laws" target="_blank" rel="noreferrer">https://cameronrwolfe.substack.com/p/llm-scaling-laws</a> [8] 搜狐. AI 变得更聪明的秘密：规模法则与涌现能力的深度解析. [在线]. Available: <a href="https://www.sohu.com/a/816414250_121798711" target="_blank" rel="noreferrer">https://www.sohu.com/a/816414250_121798711</a> [9] 阿里云. AI 规模定律的复杂性对于理解如何分配计算资源影响 AI 模型性能至关重要. [在线]. Available: <a href="https://startup.aliyun.com/info/1092259.html" target="_blank" rel="noreferrer">https://startup.aliyun.com/info/1092259.html</a> [10] TechCrunch. Current AI scaling laws are showing diminishing returns, forcing AI labs to change course. [在线]. Available: <a href="https://techcrunch.com/2024/11/20/ai-scaling-laws-are-showing-diminishing-returns-forcing-ai-labs-to-change-course/" target="_blank" rel="noreferrer">https://techcrunch.com/2024/11/20/ai-scaling-laws-are-showing-diminishing-returns-forcing-ai-labs-to-change-course/</a></p><h2 id="预训练-pre-training" tabindex="-1">预训练（Pre-training） <a class="header-anchor" href="#预训练-pre-training" aria-label="Permalink to &quot;预训练（Pre-training）&quot;">​</a></h2><p><img src="'+r+'" alt="training"></p><p>预训练是现代人工智能，特别是深度学习领域，取得突破性进展的关键范式之一。它指的是在大量无标注数据上对模型进行初步训练的过程，旨在让模型学习到通用的特征表示、语言规律或世界知识，为后续特定任务的微调奠定基础 [11]。</p><h3 id="预训练的原理与过程" tabindex="-1">预训练的原理与过程 <a class="header-anchor" href="#预训练的原理与过程" aria-label="Permalink to &quot;预训练的原理与过程&quot;">​</a></h3><p>预训练的核心思想是“授人以渔”：与其让模型从零开始学习每个特定任务，不如先让它从海量数据中学习通用的、可迁移的知识。以自然语言处理（NLP）领域为例，预训练模型通常在大规模的文本语料库（如维基百科、书籍、网页等）上进行自监督学习 [12]。这意味着模型在训练过程中不需要人工标注的标签，而是通过设计巧妙的“代理任务”（Proxy Task）来自动生成学习信号。</p><p>常见的自监督预训练任务包括：</p><ol><li><strong>掩码语言模型（Masked Language Model, MLM）</strong>：如 BERT 模型所采用的，随机遮盖输入文本中的一部分词语，然后让模型预测这些被遮盖的词语。通过这个任务，模型能够学习到词语之间的上下文关系和语义信息 [13]。</li><li><strong>下一句预测（Next Sentence Prediction, NSP）</strong>：同样是 BERT 中的任务，模型需要判断两个句子在原始文本中是否是连续的。这有助于模型理解句子间的逻辑关系和篇章结构 [13]。</li><li><strong>因果语言模型（Causal Language Model, CLM）</strong>：如 GPT 系列模型所采用的，模型根据上文预测序列中的下一个词语（token）。这种单向预测的训练方式使得模型能够生成连贯、有逻辑的文本，并学习到丰富的语言模式 [14]。</li></ol><p>通过这些自监督任务，模型在海量数据中学习到了词汇、语法、语义、甚至部分世界知识的深层表示。这个阶段的模型通常拥有庞大的参数量，能够捕捉到数据中复杂的统计规律和抽象特征。预训练的质量和数据多样性直接决定了模型基础能力的上限 [15]。</p><h3 id="预训练的优势" tabindex="-1">预训练的优势 <a class="header-anchor" href="#预训练的优势" aria-label="Permalink to &quot;预训练的优势&quot;">​</a></h3><p>预训练范式带来了多方面的显著优势：</p><ul><li><strong>数据效率</strong>：预训练利用了互联网上大量的无标注数据，避免了昂贵且耗时的人工标注过程。这使得模型能够从前所未有规模的数据中学习，从而获得强大的泛化能力 [16]。</li><li><strong>知识迁移</strong>：预训练模型学习到的通用知识和特征表示可以很容易地迁移到各种下游任务中。这意味着，对于新的任务，我们不需要从头开始训练模型，而是在预训练模型的基础上进行微调，大大缩短了开发周期和计算成本 [17]。</li><li><strong>性能提升</strong>：预训练模型通常在各种下游任务上表现出卓越的性能。由于它们已经学习了丰富的通用知识，因此在特定任务上只需要少量标注数据即可达到甚至超越从头训练的模型 [18]。</li><li><strong>加速收敛</strong>：预训练模型在微调阶段能够更快地收敛，因为它们的参数已经在一个良好的初始状态，而不是随机初始化 [19]。</li></ul><h3 id="预训练模型的发展" tabindex="-1">预训练模型的发展 <a class="header-anchor" href="#预训练模型的发展" aria-label="Permalink to &quot;预训练模型的发展&quot;">​</a></h3><p>预训练模型的发展经历了从词嵌入（如 Word2Vec、GloVe）到上下文嵌入（如 ELMo、BERT），再到大规模生成式模型（如 GPT 系列、T5、PaLM）的演变。特别是 Transformer 架构的出现，为构建更大规模、更强大的预训练模型提供了基础 [20]。这些模型在自然语言理解、文本生成、机器翻译等领域取得了里程碑式的成就，并逐渐扩展到计算机视觉（如 ViT）、多模态（如 CLIP）等领域，展现了预训练范式的普适性。</p><h3 id="挑战与展望" tabindex="-1">挑战与展望 <a class="header-anchor" href="#挑战与展望" aria-label="Permalink to &quot;挑战与展望&quot;">​</a></h3><p>尽管预训练取得了巨大成功，但也面临一些挑战。例如，训练超大规模预训练模型需要极其庞大的计算资源和能源消耗 [21]。此外，预训练数据中可能存在的偏见和有害信息也可能被模型学习并放大，导致模型输出不公平或不安全的内容 [22]。未来的研究将继续探索更高效的预训练方法、更负责任的数据收集与处理策略，以及如何更好地评估和控制预训练模型的行为。</p><p><strong>参考文献：</strong></p><p>[11] IBM. 什么是小样本学习？[在线]. Available: <a href="https://www.ibm.com/cn-zh/think/topics/few-shot-learning" target="_blank" rel="noreferrer">https://www.ibm.com/cn-zh/think/topics/few-shot-learning</a> [12] CSDN 博客. 预训练（Pre-training），人工智能领域的预训练是什么——AI 教程原创. [在线]. Available: <a href="https://blog.csdn.net/qq_26303031/article/details/141194836" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_26303031/article/details/141194836</a> [13] 知乎. 什么是预训练 AI 模型？[在线]. Available: <a href="https://www.zhihu.com/question/593535041" target="_blank" rel="noreferrer">https://www.zhihu.com/question/593535041</a> [14] AWS. 什么是 GPT AI？- 生成式预训练转换器详解. [在线]. Available: <a href="https://aws.amazon.com/cn/what-is/gpt/" target="_blank" rel="noreferrer">https://aws.amazon.com/cn/what-is/gpt/</a> [15] NVIDIA Blog. What Is a Pretrained AI Model? [在线]. Available: <a href="https://blogs.nvidia.com/blog/what-is-a-pretrained-ai-model/" target="_blank" rel="noreferrer">https://blogs.nvidia.com/blog/what-is-a-pretrained-ai-model/</a> [16] Moveworks. What Is Pre-training? [在线]. Available: <a href="https://www.moveworks.com/us/en/resources/ai-terms-glossary/pre-training" target="_blank" rel="noreferrer">https://www.moveworks.com/us/en/resources/ai-terms-glossary/pre-training</a> [17] Activeloop. What Is Pretraining and Fine-tuning. [在线]. Available: <a href="https://www.activeloop.ai/resources/glossary/pretraining-and-fine-tuning/" target="_blank" rel="noreferrer">https://www.activeloop.ai/resources/glossary/pretraining-and-fine-tuning/</a> [18] Google Cloud. 什么是 AI 模型？[在线]. Available: <a href="https://cloud.google.com/discover/what-is-an-ai-model?hl=zh-CN" target="_blank" rel="noreferrer">https://cloud.google.com/discover/what-is-an-ai-model?hl=zh-CN</a> [19] Baeldung. What Does Pre-training a Neural Network Mean? [在线]. Available: <a href="https://www.baeldung.com/cs/neural-network-pre-training" target="_blank" rel="noreferrer">https://www.baeldung.com/cs/neural-network-pre-training</a> [20] Chenyou Fan 范晨悠. 大规模预训练 AI 模型发展,现状和未来. [在线]. Available: <a href="https://fanchenyou.github.io/docs/llm.pdf" target="_blank" rel="noreferrer">https://fanchenyou.github.io/docs/llm.pdf</a> [21] 华尔街见闻. “AI 大神”重磅演讲：堆算力的“预训练”时代将结束，下一代属于“推理”. [在线]. Available: <a href="https://wallstreetcn.com/articles/3736963" target="_blank" rel="noreferrer">https://wallstreetcn.com/articles/3736963</a> [22] Knapsack AI. What Is Pretraining and Post Training AI? [在线]. Available: <a href="https://www.knapsack.ai/blog/what-is-pretraining-and-post-training-ai/" target="_blank" rel="noreferrer">https://www.knapsack.ai/blog/what-is-pretraining-and-post-training-ai/</a></p><h2 id="微调-fine-tuning" tabindex="-1">微调（Fine-tuning） <a class="header-anchor" href="#微调-fine-tuning" aria-label="Permalink to &quot;微调（Fine-tuning）&quot;">​</a></h2><p><img src="'+t+'" alt="training"></p><p>微调是在预训练模型基础上，使用特定任务的标注数据进行针对性训练的过程。它旨在将预训练模型学习到的通用知识和能力，适配到具体的下游任务或特定领域，从而显著提升模型在该任务上的性能 [23]。微调是实现 AI 模型从通用能力到专业应用有效转换的关键步骤。</p><h3 id="微调的原理与过程" tabindex="-1">微调的原理与过程 <a class="header-anchor" href="#微调的原理与过程" aria-label="Permalink to &quot;微调的原理与过程&quot;">​</a></h3><p>预训练模型虽然在海量数据上学习到了丰富的通用表示，但这些通用知识可能无法完全满足特定任务的细微需求。例如，一个在通用文本上预训练的语言模型，可能在处理法律文本或医学报告时表现不佳，因为它缺乏这些特定领域的专业词汇、表达习惯和知识结构。微调正是为了解决这一问题 [24]。</p><p>微调的过程通常包括以下几个步骤：</p><ol><li><strong>选择预训练模型</strong>：根据目标任务的性质和可用资源，选择一个合适的预训练模型作为起点。例如，对于 NLP 任务，可以选择 BERT、GPT、RoBERTa 等；对于计算机视觉任务，可以选择 ResNet、Vision Transformer 等 [25]。</li><li><strong>准备任务特定数据集</strong>：收集并标注与目标任务相关的少量数据。这些数据通常比预训练阶段的数据量小得多，但必须是高质量且与任务高度相关的 [26]。例如，如果目标是情感分析，就需要包含带有情感标签的文本数据。</li><li><strong>调整模型结构（可选）</strong>：对于某些任务，可能需要在预训练模型的顶部添加一个或几个新的层（例如，一个分类头或回归头），以适应任务的输出格式。这些新添加的层通常是随机初始化的 [27]。</li><li><strong>进行微调训练</strong>：使用任务特定数据集对预训练模型进行训练。在微调过程中，通常会使用较小的学习率，以避免破坏预训练模型已经学习到的通用知识。训练可以是对整个模型的所有参数进行微调（Full Fine-tuning），也可以是只微调新添加的层或部分层（Parameter-Efficient Fine-tuning, PEFT），例如 LoRA、Adapter 等技术，以减少计算资源和存储需求 [28]。</li><li><strong>评估与部署</strong>：在独立的验证集上评估微调后模型的性能，并根据需要进行调整。一旦达到满意效果，即可将模型部署到实际应用中。</li></ol><h3 id="微调的优势" tabindex="-1">微调的优势 <a class="header-anchor" href="#微调的优势" aria-label="Permalink to &quot;微调的优势&quot;">​</a></h3><p>微调范式带来了多方面的显著优势，使其成为当前 AI 应用开发的主流方法：</p><ul><li><strong>高效性</strong>：相比从头开始训练一个模型，微调所需的计算资源和时间大大减少。预训练模型已经学习了大量的底层特征和通用知识，微调只需要在此基础上进行少量调整即可 [29]。</li><li><strong>数据效率</strong>：微调通常只需要相对较少的标注数据。这对于那些难以获取大量标注数据的领域（如医疗、法律等）尤为重要，大大降低了数据标注的成本和门槛 [30]。</li><li><strong>性能提升</strong>：微调能够显著提升模型在特定任务上的性能。通过将通用知识与任务特定知识相结合，模型能够更好地理解和处理特定领域的问题 [31]。</li><li><strong>泛化能力</strong>：预训练模型学习到的通用表示有助于微调后的模型在面对少量未见过的数据时，依然保持较好的泛化能力 [32]。</li><li><strong>快速迭代</strong>：微调使得 AI 模型的开发和部署过程更加敏捷。开发者可以快速地针对不同的任务或数据集进行模型适配和优化。</li></ul><h3 id="微调的类型与发展" tabindex="-1">微调的类型与发展 <a class="header-anchor" href="#微调的类型与发展" aria-label="Permalink to &quot;微调的类型与发展&quot;">​</a></h3><p>随着 AI 技术的发展，微调也演变出多种形式：</p><ul><li><strong>全量微调（Full Fine-tuning）</strong>：更新预训练模型的所有参数。这种方法通常能达到最佳性能，但计算成本较高，且容易在小数据集上过拟合 [33]。</li><li><strong>参数高效微调（Parameter-Efficient Fine-tuning, PEFT）</strong>：只更新模型的一小部分参数，或引入少量额外参数进行训练。PEFT 方法如 LoRA (Low-Rank Adaptation)、Prefix-tuning、Prompt-tuning 等，能够大幅减少训练参数量和计算资源，同时保持甚至超越全量微调的性能，特别适用于大型模型 [34]。</li><li><strong>指令微调（Instruction Tuning）</strong>：通过在各种任务上使用指令格式的数据进行微调，使模型能够更好地理解和遵循人类指令，提高模型的泛化能力和可用性 [35]。</li><li><strong>对齐微调（Alignment Fine-tuning）</strong>：通过人类反馈或其他对齐技术（如 RLHF），使模型输出更符合人类的价值观、偏好和安全标准 [36]。</li></ul><p>微调是连接通用 AI 能力与特定应用场景的桥梁，它的发展使得 AI 技术能够更广泛、更高效地服务于各行各业。</p><p><strong>参考文献：</strong></p><p>[23] Microsoft Learn. AI 模型微调概念. [在线]. Available: <a href="https://learn.microsoft.com/zh-cn/windows/ai/fine-tuning" target="_blank" rel="noreferrer">https://learn.microsoft.com/zh-cn/windows/ai/fine-tuning</a> [24] IBM. What is Fine-Tuning? [在线]. Available: <a href="https://www.ibm.com/think/topics/fine-tuning" target="_blank" rel="noreferrer">https://www.ibm.com/think/topics/fine-tuning</a> [25] OpenAI API. Fine-tuning. [在线]. Available: <a href="https://platform.openai.com/docs/guides/fine-tuning" target="_blank" rel="noreferrer">https://platform.openai.com/docs/guides/fine-tuning</a> [26] TechTarget. What Is Fine-Tuning in Machine Learning and AI? [在线]. Available: <a href="https://www.techtarget.com/searchenterpriseai/definition/fine-tuning" target="_blank" rel="noreferrer">https://www.techtarget.com/searchenterpriseai/definition/fine-tuning</a> [27] Coursera. What Is Fine-Tuning? [在线]. Available: <a href="https://www.coursera.org/articles/what-is-fine-tuning" target="_blank" rel="noreferrer">https://www.coursera.org/articles/what-is-fine-tuning</a> [28] Google AI for Developers. Gemma 模型微调. [在线]. Available: <a href="https://ai.google.dev/gemma/docs/tune?hl=zh-cn" target="_blank" rel="noreferrer">https://ai.google.dev/gemma/docs/tune?hl=zh-cn</a> [29] CSDN 博客. 大家都在说的 AI 大模型微调到底是什么？最易懂的 AI 知识科普！一篇为. [在线]. Available: <a href="https://blog.csdn.net/YoungOne2333/article/details/142481589" target="_blank" rel="noreferrer">https://blog.csdn.net/YoungOne2333/article/details/142481589</a> [30] AWS. 炼石成丹：大语言模型微调实战系列（一）数据准备篇. [在线]. Available: <a href="https://aws.amazon.com/cn/blogs/china/practical-series-on-fine-tuning-large-language-models-part-one/" target="_blank" rel="noreferrer">https://aws.amazon.com/cn/blogs/china/practical-series-on-fine-tuning-large-language-models-part-one/</a> [31] 知乎专栏. 通俗解读大模型微调(Fine Tuning). [在线]. Available: <a href="https://zhuanlan.zhihu.com/p/650287173" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/650287173</a> [32] ZHIPU AI OPEN PLATFORM. Model Fine-tuning. [在线]. Available: <a href="https://open.bigmodel.cn/dev/howuse/finetuning" target="_blank" rel="noreferrer">https://open.bigmodel.cn/dev/howuse/finetuning</a> [33] Wikipedia. Fine-tuning (deep learning). [在线]. Available: <a href="https://en.wikipedia.org/wiki/Fine-tuning_(deep_learning)" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Fine-tuning_(deep_learning)</a> [34] Google Cloud. Gemini 的模型调优概览. [在线]. Available: <a href="https://cloud.google.com/vertex-ai/generative-ai/docs/models/tune-gemini-overview?hl=zh-cn" target="_blank" rel="noreferrer">https://cloud.google.com/vertex-ai/generative-ai/docs/models/tune-gemini-overview?hl=zh-cn</a> [35] YouTube. 让 AI 更懂你：10 分钟教你如何做 chatGPT 微调 Fine-Tune. [在线]. Available: <a href="https://www.youtube.com/watch?v=TTrYhNRUpwo" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=TTrYhNRUpwo</a> [36] Databricks. Understanding Fine-Tuning in AI and ML. [在线]. Available: <a href="https://www.databricks.com/glossary/fine-tuning" target="_blank" rel="noreferrer">https://www.databricks.com/glossary/fine-tuning</a></p><h2 id="rlhf-人类反馈强化学习" tabindex="-1">RLHF（人类反馈强化学习） <a class="header-anchor" href="#rlhf-人类反馈强化学习" aria-label="Permalink to &quot;RLHF（人类反馈强化学习）&quot;">​</a></h2><p><img src="'+n+'" alt="training"></p><p>人类反馈强化学习（Reinforcement Learning from Human Feedback, RLHF）是一种强大的训练范式，旨在使大型语言模型（LLMs）的输出更符合人类的偏好、价值观和指令 [37]。它通过引入人类的判断作为奖励信号，有效地解决了传统强化学习中奖励函数难以设计的问题，尤其是在处理开放式、主观性强的任务时 [38]。RLHF 是 ChatGPT 等先进 LLM 能够生成高质量、安全且有用响应的关键技术之一。</p><h3 id="rlhf-的原理与过程" tabindex="-1">RLHF 的原理与过程 <a class="header-anchor" href="#rlhf-的原理与过程" aria-label="Permalink to &quot;RLHF 的原理与过程&quot;">​</a></h3><p>RLHF 通常涉及三个核心步骤：</p><ol><li><strong>预训练语言模型（Pre-trained Language Model）</strong>：首先，需要一个在大规模文本数据上预训练好的语言模型（如 GPT-3）。这个模型已经具备了生成连贯文本和理解语言模式的基础能力 [39]。</li><li><strong>训练奖励模型（Reward Model, RM）</strong>： <ul><li><strong>数据收集</strong>：从预训练语言模型中抽取一系列输出（例如，对特定提示的多个不同响应）。然后，人类标注者对这些输出进行排序或评分，以表达他们对不同响应的偏好。例如，对于同一个问题，人类会选择哪个回答更好、更安全、更符合预期 [40]。</li><li><strong>模型训练</strong>：使用这些人类偏好数据来训练一个单独的奖励模型。奖励模型是一个监督学习模型，它的任务是学习预测人类对任何给定模型输出的偏好分数。这个模型本质上是将人类的隐式偏好转化为一个可量化的奖励信号 [41]。</li></ul></li><li><strong>使用强化学习优化语言模型</strong>： <ul><li><strong>策略优化</strong>：将训练好的奖励模型作为强化学习环境中的奖励函数。预训练语言模型被视为一个策略（Policy），其目标是最大化奖励模型给出的分数。通常采用近端策略优化（Proximal Policy Optimization, PPO）等强化学习算法来微调语言模型 [42]。</li><li><strong>迭代优化</strong>：在强化学习过程中，语言模型会生成新的响应，奖励模型会对其进行评分，然后语言模型根据这些评分调整其参数，以生成更高奖励的响应。这个过程会迭代进行，使得语言模型逐渐学会生成更符合人类偏好的输出 [43]。</li></ul></li></ol><h3 id="rlhf-的优势与影响" tabindex="-1">RLHF 的优势与影响 <a class="header-anchor" href="#rlhf-的优势与影响" aria-label="Permalink to &quot;RLHF 的优势与影响&quot;">​</a></h3><p>RLHF 的引入极大地提升了 LLMs 的实用性和安全性：</p><ul><li><strong>对齐人类意图</strong>：RLHF 能够有效地将模型的行为与复杂的人类价值观和意图对齐，使其输出更具帮助性、真实性和无害性 [44]。这对于构建用户友好且负责任的 AI 系统至关重要。</li><li><strong>处理主观性任务</strong>：对于那些没有明确正确答案或需要主观判断的任务（如创意写作、开放式对话），RLHF 提供了一种有效的方法来优化模型，使其输出更符合人类的审美或偏好 [45]。</li><li><strong>减少有害输出</strong>：通过人类反馈，模型可以学习避免生成有毒、偏见或不安全的内容，从而提高 AI 系统的鲁棒性和可靠性 [46]。</li><li><strong>提升用户体验</strong>：经过 RLHF 训练的模型通常能提供更自然、更符合用户期望的交互体验，从而增强用户对 AI 系统的信任和满意度 [47]。</li></ul><h3 id="rlhf-的挑战与发展" tabindex="-1">RLHF 的挑战与发展 <a class="header-anchor" href="#rlhf-的挑战与发展" aria-label="Permalink to &quot;RLHF 的挑战与发展&quot;">​</a></h3><p>尽管 RLHF 取得了显著成功，但也面临一些挑战：</p><ul><li><strong>数据收集成本</strong>：收集高质量的人类偏好数据是昂贵且耗时的，尤其是在需要大量多样化反馈时 [48]。</li><li><strong>奖励模型偏差</strong>：奖励模型的好坏直接影响最终语言模型的性能。如果奖励模型本身存在偏差或未能准确捕捉人类偏好，可能会导致语言模型学到不理想的行为 [49]。</li><li><strong>可扩展性</strong>：随着模型规模的增大，RLHF 的训练过程变得更加复杂和计算密集 [50]。</li></ul><p>为了解决这些挑战，研究人员正在探索 RLHF 的变体和替代方案，例如：</p><ul><li><strong>RLAIF (Reinforcement Learning from AI Feedback)</strong>：使用 AI 模型而非人类来提供反馈，以提高数据收集的效率和可扩展性 [51]。</li><li><strong>DPO (Direct Preference Optimization)</strong>：一种更简单、更稳定的对齐方法，它直接优化语言模型以匹配人类偏好，而无需训练单独的奖励模型 [52]。</li></ul><p>RLHF 及其后续发展代表了 AI 模型训练的一个重要方向，即如何将人类的智能和价值观有效地融入到 AI 系统中，使其不仅强大，而且有益于人类社会。</p><p><strong>参考文献：</strong></p><p>[37] AWS. What is RLHF? - Reinforcement Learning from Human Feedback. [在线]. Available: <a href="https://aws.amazon.com/what-is/reinforcement-learning-from-human-feedback/" target="_blank" rel="noreferrer">https://aws.amazon.com/what-is/reinforcement-learning-from-human-feedback/</a> [38] IBM. What Is Reinforcement Learning From Human Feedback (RLHF)? [在线]. Available: <a href="https://www.ibm.com/think/topics/rlhf" target="_blank" rel="noreferrer">https://www.ibm.com/think/topics/rlhf</a> [39] Hugging Face. Illustrating Reinforcement Learning from Human Feedback (RLHF). [在线]. Available: <a href="https://huggingface.co/blog/rlhf" target="_blank" rel="noreferrer">https://huggingface.co/blog/rlhf</a> [40] Wikipedia. Reinforcement learning from human feedback. [在线]. Available: <a href="https://en.wikipedia.org/wiki/Reinforcement_learning_from_human_feedback" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Reinforcement_learning_from_human_feedback</a> [41] Coursera. RLHF: Understanding Reinforcement Learning from Human Feedback. [在线]. Available: <a href="https://www.coursera.org/articles/rlhf" target="_blank" rel="noreferrer">https://www.coursera.org/articles/rlhf</a> [42] CMU ML Blog. RLHF 101: A Technical Tutorial on Reinforcement Learning from Human Feedback. [在线]. Available: <a href="https://blog.ml.cmu.edu/2025/06/01/rlhf-101-a-technical-tutorial-on-reinforcement-learning-from-human-feedback/" target="_blank" rel="noreferrer">https://blog.ml.cmu.edu/2025/06/01/rlhf-101-a-technical-tutorial-on-reinforcement-learning-from-human-feedback/</a> [43] YouTube. Reinforcement Learning from Human Feedback (RLHF) Explained. [在线]. Available: <a href="https://www.youtube.com/watch?v=T_X4XFwKX8k&amp;pp=0gcJCfwAo7VqN5tD" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=T_X4XFwKX8k&amp;pp=0gcJCfwAo7VqN5tD</a> [44] arXiv. Training language models to follow instructions with human feedback. [在线]. Available: <a href="https://arxiv.org/abs/2203.02155" target="_blank" rel="noreferrer">https://arxiv.org/abs/2203.02155</a> [45] Alation. What is Reinforcement Learning from Human Feedback (RLHF)? [在线]. Available: <a href="https://www.alation.com/blog/what-is-rlhf-reinforcement-learning-human-feedback/" target="_blank" rel="noreferrer">https://www.alation.com/blog/what-is-rlhf-reinforcement-learning-human-feedback/</a> [46] SuperAnnotate. Reinforcement learning with human feedback (RLHF) for LLMs. [在线]. Available: <a href="https://www.superannotate.com/blog/rlhf-for-llm" target="_blank" rel="noreferrer">https://www.superannotate.com/blog/rlhf-for-llm</a> [47] Towards Data Science. Reinforcement Learning from Human Feedback, Explained Simply. [在线]. Available: <a href="https://towardsdatascience.com/explained-simply-reinforcement-learning-from-human-feedback/" target="_blank" rel="noreferrer">https://towardsdatascience.com/explained-simply-reinforcement-learning-from-human-feedback/</a> [48] arXiv. A Survey of Reinforcement Learning from Human Feedback. [在线]. Available: <a href="https://arxiv.org/abs/2312.14925" target="_blank" rel="noreferrer">https://arxiv.org/abs/2312.14925</a> [49] RLHF Book. Reinforcement Learning from Human Feedback. [在线]. Available: <a href="https://rlhfbook.com/book.pdf" target="_blank" rel="noreferrer">https://rlhfbook.com/book.pdf</a> [50] AssemblyAI. How Reinforcement Learning from AI Feedback works. [在线]. Available: <a href="https://assemblyai.com/blog/how-reinforcement-learning-from-ai-feedback-works" target="_blank" rel="noreferrer">https://assemblyai.com/blog/how-reinforcement-learning-from-ai-feedback-works</a> [51] DataCamp. RLAIF: What is Reinforcement Learning From AI Feedback? [在线]. Available: <a href="https://www.datacamp.com/blog/rlaif-reinforcement-learning-from-ai-feedback" target="_blank" rel="noreferrer">https://www.datacamp.com/blog/rlaif-reinforcement-learning-from-ai-feedback</a> [52] arXiv. RLAIF vs. RLHF: Scaling Reinforcement Learning from Human. [在线]. Available: <a href="https://arxiv.org/abs/2309.00267" target="_blank" rel="noreferrer">https://arxiv.org/abs/2309.00267</a></p><h2 id="少样本学习-few-shot-learning" tabindex="-1">少样本学习（Few-shot Learning） <a class="header-anchor" href="#少样本学习-few-shot-learning" aria-label="Permalink to &quot;少样本学习（Few-shot Learning）&quot;">​</a></h2><p><img src="'+i+'" alt="training"></p><p>少样本学习（Few-shot Learning, FSL）是指模型仅通过少量标注数据就能快速适应新任务的能力。在传统机器学习中，模型通常需要大量的标注数据才能达到良好的性能。然而，在许多现实场景中，获取大量标注数据是昂贵、耗时甚至不可能的。少样本学习旨在模拟人类从少量示例中学习的能力，使 AI 模型在数据稀缺的环境下也能高效工作 [53]。</p><h3 id="少样本学习的原理与挑战" tabindex="-1">少样本学习的原理与挑战 <a class="header-anchor" href="#少样本学习的原理与挑战" aria-label="Permalink to &quot;少样本学习的原理与挑战&quot;">​</a></h3><p>少样本学习的核心挑战在于如何避免模型在少量数据上过拟合，并有效地将从其他任务或领域学到的知识迁移到新任务上。其基本思想是，模型不直接从少量样本中学习任务的全部知识，而是利用其在大量数据上预训练时获得的通用表示能力和学习能力 [54]。</p><p>少样本学习的实现方法通常可以分为几类：</p><ol><li><strong>元学习（Meta-learning）</strong>：也称为“学会学习”（Learning to Learn）。元学习的目标是训练一个模型，使其能够快速适应新任务，而不是直接解决特定任务。它通过在多个相关任务上进行训练，学习如何有效地从少量样本中提取信息并进行泛化 [55]。例如，MAML（Model-Agnostic Meta-Learning）就是一种经典的元学习算法，它学习一个良好的模型初始化参数，使得模型在新任务上经过少量梯度更新后就能表现良好 [56]。</li><li><strong>度量学习（Metric Learning）</strong>：这类方法旨在学习一个度量空间，使得在少量样本中，同类样本之间的距离较近，不同类样本之间的距离较远。当遇到新样本时，可以通过计算其与已知少量样本的距离来判断其类别 [57]。例如，Siamese Network 和 Prototypical Network 等都属于度量学习范畴 [58]。</li><li><strong>数据增强与生成</strong>：通过对少量样本进行数据增强，或者利用生成模型（如 GAN、VAE）生成新的合成数据，来扩充训练集，从而缓解数据稀缺问题 [59]。</li><li><strong>预训练与提示（Pre-training and Prompting）</strong>：对于大型语言模型（LLMs）而言，少样本学习的能力主要体现在“上下文学习”（In-context Learning）中。模型在预训练阶段学习了海量的语言模式和世界知识，这使得它能够在接收到包含少量示例的提示（Prompt）时，理解任务的意图和输入输出格式，并生成符合期望的结果，而无需进行模型参数的修改 [60]。这种能力极大地降低了 LLMs 在新任务上的部署门槛。</li></ol><h3 id="少样本学习的优势与应用" tabindex="-1">少样本学习的优势与应用 <a class="header-anchor" href="#少样本学习的优势与应用" aria-label="Permalink to &quot;少样本学习的优势与应用&quot;">​</a></h3><p>少样本学习在许多实际应用中具有重要价值：</p><ul><li><strong>降低数据标注成本</strong>：在许多领域，获取大量高质量的标注数据是巨大的挑战。少样本学习能够显著减少对标注数据的需求，从而降低成本和时间 [61]。</li><li><strong>解决冷启动问题</strong>：对于新出现的任务或类别，在没有足够历史数据的情况下，少样本学习能够帮助模型快速启动并提供初步的服务 [62]。</li><li><strong>适应数据稀疏领域</strong>：在医学影像诊断、珍稀物种识别、小语种翻译等数据稀疏的领域，少样本学习提供了有效的解决方案 [63]。</li><li><strong>提高模型适应性</strong>：使得 AI 模型能够更灵活地适应不断变化的环境和新的任务需求，增强了 AI 系统的鲁棒性和通用性 [64]。</li><li><strong>推动通用人工智能发展</strong>：少样本学习是实现更通用、更高效人工智能的关键一步，因为它模拟了人类快速学习和适应新知识的能力 [65]。</li></ul><h3 id="挑战与展望-1" tabindex="-1">挑战与展望 <a class="header-anchor" href="#挑战与展望-1" aria-label="Permalink to &quot;挑战与展望&quot;">​</a></h3><p>尽管少样本学习取得了显著进展，但仍面临一些挑战：</p><ul><li><strong>泛化能力</strong>：如何在极少量样本上实现更好的泛化，避免对特定示例的过拟合，仍然是一个活跃的研究方向 [66]。</li><li><strong>任务多样性</strong>：目前的少样本学习方法在某些特定类型的任务上表现良好，但在面对高度多样化或结构复杂的新任务时，其效果可能受限 [67]。</li><li><strong>可解释性</strong>：少样本学习模型在决策过程中如何利用少量样本和预训练知识，其内部机制仍需更深入的理解和解释 [68]。</li></ul><p>未来的研究将继续探索更有效的元学习算法、更强大的预训练模型、以及结合符号推理等多种范式，以进一步提升少样本学习的能力，使其在更广泛的实际应用中发挥作用。</p><p><strong>参考文献：</strong></p><p>[53] IBM. 什么是小样本学习？[在线]. Available: <a href="https://www.ibm.com/cn-zh/think/topics/few-shot-learning" target="_blank" rel="noreferrer">https://www.ibm.com/cn-zh/think/topics/few-shot-learning</a> [54] DigitalOcean. Everything you need to know about Few-Shot Learning. [在线]. Available: <a href="https://www.digitalocean.com/community/tutorials/few-shot-learning" target="_blank" rel="noreferrer">https://www.digitalocean.com/community/tutorials/few-shot-learning</a> [55] Pareto.AI. The Complete Guide to Few-Shot Learning. [在线]. Available: <a href="https://pareto.ai/blog/few-shot-learning" target="_blank" rel="noreferrer">https://pareto.ai/blog/few-shot-learning</a> [56] 知乎专栏. Few-shot learning（少样本学习）入门. [在线]. Available: <a href="https://zhuanlan.zhihu.com/p/156830039" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/156830039</a> [57] CSDN 博客. Few-Shot Learning（少样本学习）. [在线]. Available: <a href="https://www.cnblogs.com/BlogNetSpace/p/18632033" target="_blank" rel="noreferrer">https://www.cnblogs.com/BlogNetSpace/p/18632033</a> [58] 飞桨 AI Studio. 小样本学习(Few-Shot Learning)（一）. [在线]. Available: <a href="https://aistudio.baidu.com/aistudio/projectdetail/2342018?channelType=0&amp;channel=0" target="_blank" rel="noreferrer">https://aistudio.baidu.com/aistudio/projectdetail/2342018?channelType=0&amp;channel=0</a> [59] CSDN 博客. 如何通过少样本学习提升 AI 模型性能. [在线]. Available: <a href="https://blog.csdn.net/stjklkjhgffxw/article/details/144405575" target="_blank" rel="noreferrer">https://blog.csdn.net/stjklkjhgffxw/article/details/144405575</a> [60] Prompt Engineering Guide. 少样本提示. [在线]. Available: <a href="https://www.promptingguide.ai/zh/techniques/fewshot" target="_blank" rel="noreferrer">https://www.promptingguide.ai/zh/techniques/fewshot</a> [61] DataCamp. What is Few-Shot Learning? Unlocking Insights with Limited Data. [在线]. Available: <a href="https://www.datacamp.com/blog/what-is-few-shot-learning" target="_blank" rel="noreferrer">https://www.datacamp.com/blog/what-is-few-shot-learning</a> [62] Analytics Vidhya. An Introduction to Few-Shot Learning. [在线]. Available: <a href="https://www.analyticsvidhya.com/blog/2021/05/an-introduction-to-few-shot-learning/" target="_blank" rel="noreferrer">https://www.analyticsvidhya.com/blog/2021/05/an-introduction-to-few-shot-learning/</a> [63] Built In. What Is Few Shot Learning? (Definition, Applications). [在线]. Available: <a href="https://builtin.com/machine-learning/few-shot-learning" target="_blank" rel="noreferrer">https://builtin.com/machine-learning/few-shot-learning</a> [64] V7 Labs. A Step-by-step Guide to Few-Shot Learning. [在线]. Available: <a href="https://www.v7labs.com/blog/few-shot-learning-guide" target="_blank" rel="noreferrer">https://www.v7labs.com/blog/few-shot-learning-guide</a> [65] Neptune.ai. Understanding Few-Shot Learning in Computer Vision. [在线]. Available: <a href="https://neptune.ai/blog/understanding-few-shot-learning-in-computer-vision" target="_blank" rel="noreferrer">https://neptune.ai/blog/understanding-few-shot-learning-in-computer-vision</a> [66] arXiv. A Summary of Approaches to Few-Shot Learning. [在线]. Available: <a href="https://arxiv.org/abs/2203.04291" target="_blank" rel="noreferrer">https://arxiv.org/abs/2203.04291</a> [67] UBIAI NLP. Step-by-Step Guide to Mastering Few-Shot Learning. [在线]. Available: <a href="https://medium.com/ubiai-nlp/step-by-step-guide-to-mastering-few-shot-learning-a673054167a0" target="_blank" rel="noreferrer">https://medium.com/ubiai-nlp/step-by-step-guide-to-mastering-few-shot-learning-a673054167a0</a> [68] Microsoft Learn. 零樣本學習和少樣本學習. [在线]. Available: <a href="https://learn.microsoft.com/zh-tw/dotnet/ai/conceptual/zero-shot-learning" target="_blank" rel="noreferrer">https://learn.microsoft.com/zh-tw/dotnet/ai/conceptual/zero-shot-learning</a></p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本文详细探讨了当前人工智能领域中五种核心的训练方法：规模法则、预训练、微调、人类反馈强化学习（RLHF）和少样本学习。这些方法共同构成了现代 AI，特别是大型模型，得以实现其强大能力和广泛应用的基础。</p><ul><li><strong>规模法则</strong>揭示了模型性能与计算资源、数据量和模型参数之间存在的普遍幂律关系，为 AI 的发展提供了“大力出奇迹”的指导原则，并解释了“涌现能力”的现象。</li><li><strong>预训练</strong>通过在海量无标注数据上进行自监督学习，使模型获得了通用的语言理解和世界知识，为后续任务的特化奠定了坚实基础。</li><li><strong>微调</strong>则在此基础上，利用少量特定任务的标注数据，将预训练模型的通用能力适配到具体应用场景，实现了高效的知识迁移和性能优化。</li><li><strong>RLHF</strong>引入了人类的偏好作为奖励信号，有效地解决了 AI 模型与人类价值观对齐的挑战，使得模型输出更具帮助性、真实性和安全性。</li><li><strong>少样本学习</strong>则展现了模型在数据稀缺场景下快速适应新任务的能力，极大地降低了 AI 部署的门槛和数据标注的成本。</li></ul><p>这些训练方法并非孤立存在，而是相互关联、层层递进。预训练为微调提供了强大的基础，微调使得预训练模型的潜力得以释放，RLHF 则进一步优化了模型的行为以符合人类期望，而少样本学习则是在这些强大模型基础上展现出的高级能力。它们共同推动了 AI 技术从理论研究走向广泛应用，深刻改变了我们与信息、与智能系统互动的方式。</p><p>展望未来，AI 训练方法的研究将继续朝着更高效、更负责任、更具通用性的方向发展。这包括探索更节能的训练范式、开发更强大的多模态预训练模型、研究更精细的对齐技术以确保 AI 的伦理和安全，以及提升模型在极端数据稀缺条件下的学习能力。随着这些方法的不断演进和融合，我们有理由相信，人工智能将继续以超乎想象的速度发展，为人类社会带来更多创新和变革。</p>',89)]))}const k=o(g,[["render",c]]);export{A as __pageData,k as default};
